//! The request-body half of FastAPI's request validation for crm-api's Body models (pydantic v2,
//! lax mode, `from_attributes`): the body read as FastAPI reads it, then each model validated
//! against its JSON schema in models.json (generated by gen_openapi.py from the Python models),
//! with the same coercions and the same error objects in the same order.

use std::sync::OnceLock;

use serde_json::{json, Map, Value};
use vexa_native_kit::pyd;

const MODELS: &str = include_str!("models.json");

fn models() -> &'static Value {
    static M: OnceLock<Value> = OnceLock::new();
    M.get_or_init(|| serde_json::from_str(MODELS).expect("models.json is valid JSON"))
}

/// The schema of one Body model (with its defaults filled and "x-strict" / "x-forbid" marks).
pub fn schema(name: &str) -> &'static Value {
    models().get(name).unwrap_or_else(|| panic!("models.json has no model {name}"))
}

/// What the body read produced before validation.
#[derive(Debug, Clone, PartialEq)]
pub enum Body {
    /// No body, or the JSON document `null`: the body is missing.
    Missing,
    /// A JSON document.
    Json(Value),
    /// Bytes that were not read as JSON (another content type): pydantic sees the text.
    Raw(String),
}

/// Why the body could not be read.
#[derive(Debug, Clone, PartialEq)]
pub enum BodyFail {
    /// json.JSONDecodeError: 422 with one json_invalid error.
    Decode(Value),
    /// Any other read failure: 400 "There was an error parsing the body".
    Parse,
    /// The bytes of a non-JSON body are not UTF-8: the error answer itself fails (500).
    Internal,
}

/// email.message's view of a Content-Type: (maintype, subtype), lower-case; text/plain when the
/// value has no "/".
fn content_type(value: &str) -> (String, String) {
    let main = value.split(';').next().unwrap_or("").trim().to_ascii_lowercase();
    match main.split_once('/') {
        Some((a, b)) if !a.is_empty() && !b.is_empty() && !b.contains('/') => (a.to_owned(), b.to_owned()),
        _ => ("text".into(), "plain".into()),
    }
}

/// FastAPI's body read for a JSON body field: JSON only for an application/json or +json content
/// type (strict content type: none at all is not JSON).
pub fn read(content_type_header: Option<&str>, bytes: &[u8]) -> Result<Body, BodyFail> {
    if bytes.is_empty() {
        return Ok(Body::Missing);
    }
    let json = match content_type_header {
        None | Some("") => false,
        Some(ct) => {
            let (main, sub) = content_type(ct);
            main == "application" && (sub == "json" || sub.ends_with("+json"))
        }
    };
    if !json {
        return match std::str::from_utf8(bytes) {
            Ok(t) => Ok(Body::Raw(t.to_owned())),
            Err(_) => Err(BodyFail::Internal),
        };
    }
    let text = bytes.strip_prefix(b"\xef\xbb\xbf").unwrap_or(bytes);
    let Ok(text) = std::str::from_utf8(text) else { return Err(BodyFail::Parse) };
    match vexa_native_kit::pyjson_decode::loads(text) {
        Ok(Value::Null) => Ok(Body::Missing),
        Ok(v) => Ok(Body::Json(v)),
        Err(e) => Err(BodyFail::Decode(
            json!({"type": "json_invalid", "loc": ["body", e.pos], "msg": "JSON decode error", "input": {}, "ctx": {"error": e.msg}}),
        )),
    }
}

/// Validate a body against the named model: the model's fields in order with defaults filled, or
/// FastAPI's error list (loc starting at "body").
pub fn body(name: &str, input: &Body) -> Result<Map<String, Value>, Vec<Value>> {
    let loc = [json!("body")];
    let mut errs = Vec::new();
    let out = match input {
        Body::Missing => {
            errs.push(pyd::missing(&loc, Value::Null));
            None
        }
        Body::Json(v) => model(schema(name), v, &loc, &mut errs),
        Body::Raw(t) => model(schema(name), &Value::String(t.clone()), &loc, &mut errs),
    };
    match out {
        Some(m) if errs.is_empty() => Ok(m),
        _ => Err(errs),
    }
}

fn push(loc: &[Value], part: impl Into<Value>) -> Vec<Value> {
    let mut l = loc.to_vec();
    l.push(part.into());
    l
}

/// A model: every field in definition order (present: validated; absent: missing when required,
/// else its default), then each extra key when the model forbids extras.
pub fn model(schema: &Value, input: &Value, loc: &[Value], errs: &mut Vec<Value>) -> Option<Map<String, Value>> {
    let Some(obj) = input.as_object() else {
        errs.push(pyd::error(
            "model_attributes_type",
            loc,
            "Input should be a valid dictionary or object to extract fields from".into(),
            input.clone(),
            None,
        ));
        return None;
    };
    let required: Vec<&str> = schema
        .get("required")
        .and_then(Value::as_array)
        .map(|r| r.iter().filter_map(Value::as_str).collect())
        .unwrap_or_default();
    let empty = Map::new();
    let props = schema.get("properties").and_then(Value::as_object).unwrap_or(&empty);
    let before = errs.len();
    let mut out = Map::new();
    for (name, prop) in props {
        let here = push(loc, name.as_str());
        match obj.get(name) {
            Some(v) => {
                let strict = prop.get("x-strict") == Some(&Value::Bool(true));
                if let Some(got) = value(prop, v, &here, strict, errs) {
                    out.insert(name.clone(), got);
                }
            }
            None if required.contains(&name.as_str()) => errs.push(pyd::missing(&here, input.clone())),
            None => {
                out.insert(name.clone(), prop.get("default").cloned().unwrap_or(Value::Null));
            }
        }
    }
    if schema.get("x-forbid") == Some(&Value::Bool(true)) {
        for (k, v) in obj {
            if !props.contains_key(k) {
                errs.push(pyd::error("extra_forbidden", &push(loc, k.as_str()), "Extra inputs are not permitted".into(), v.clone(), None));
            }
        }
    }
    (errs.len() == before).then_some(out)
}

/// The one non-null branch of `anyOf: [X, null]`.
fn nullable(schema: &Value) -> Option<&Value> {
    let branches = schema.get("anyOf")?.as_array()?;
    if !branches.iter().any(|b| b.get("type").and_then(Value::as_str) == Some("null")) {
        return None;
    }
    branches.iter().find(|b| b.get("type").and_then(Value::as_str) != Some("null"))
}

fn plural(n: u64) -> &'static str {
    if n == 1 {
        ""
    } else {
        "s"
    }
}

/// One field value.
pub fn value(schema: &Value, v: &Value, loc: &[Value], strict: bool, errs: &mut Vec<Value>) -> Option<Value> {
    if let Some(inner) = nullable(schema) {
        if v.is_null() {
            return Some(Value::Null);
        }
        return value(inner, v, loc, strict, errs);
    }
    if let Some(name) = schema.get("$ref").and_then(Value::as_str) {
        return model(self::schema(name), v, loc, errs).map(Value::Object);
    }
    if schema.get("enum").is_some() {
        return pyd::value(schema, v, loc, errs);
    }
    match schema.get("type").and_then(Value::as_str).unwrap_or("") {
        "array" => {
            let Some(items) = v.as_array() else {
                errs.push(pyd::error("list_type", loc, "Input should be a valid list".into(), v.clone(), None));
                return None;
            };
            let n = items.len() as u64;
            if let Some(max) = schema.get("maxItems").and_then(Value::as_u64) {
                if n > max {
                    errs.push(pyd::error(
                        "too_long",
                        loc,
                        format!("List should have at most {max} item{} after validation, not {n}", plural(max)),
                        v.clone(),
                        Some(json!({"field_type": "List", "max_length": max, "actual_length": n})),
                    ));
                    return None;
                }
            }
            let item_schema = schema.get("items").cloned().unwrap_or(json!({}));
            let before = errs.len();
            let out: Vec<Value> =
                items.iter().enumerate().filter_map(|(i, item)| value(&item_schema, item, &push(loc, i), false, errs)).collect();
            if errs.len() > before {
                return None;
            }
            if let Some(min) = schema.get("minItems").and_then(Value::as_u64) {
                if n < min {
                    errs.push(pyd::error(
                        "too_short",
                        loc,
                        format!("List should have at least {min} item{} after validation, not {n}", plural(min)),
                        v.clone(),
                        Some(json!({"field_type": "List", "min_length": min, "actual_length": n})),
                    ));
                    return None;
                }
            }
            Some(Value::Array(out))
        }
        "boolean" if strict => match v {
            Value::Bool(_) => Some(v.clone()),
            _ => {
                errs.push(pyd::error("bool_type", loc, "Input should be a valid boolean".into(), v.clone(), None));
                None
            }
        },
        "integer" if strict => match v {
            Value::Number(n) if n.is_i64() || n.is_u64() => pyd::value(schema, v, loc, errs),
            _ => {
                errs.push(pyd::error("int_type", loc, "Input should be a valid integer".into(), v.clone(), None));
                None
            }
        },
        _ => pyd::value(schema, v, loc, errs),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const CASES: &str = include_str!("validate_cases.json");

    /// The model each route's body is validated with.
    fn model_of(path: &str) -> &'static str {
        crate::api::body_model(path).unwrap_or_else(|| panic!("no body model for {path}"))
    }

    fn hex(s: &str) -> Vec<u8> {
        (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
    }

    /// Every body the Python service was sent (gen_openapi.py): the same 422 error list, the same
    /// 400, or no error where FastAPI let the body through to the route.
    #[test]
    fn same_answers_as_fastapi() {
        let cases: Vec<Value> = serde_json::from_str(CASES).unwrap();
        let mut failed = Vec::new();
        for c in &cases {
            let path = c["path"].as_str().unwrap();
            let bytes = hex(c["body_hex"].as_str().unwrap());
            let ct = c["content_type"].as_str();
            let got: Result<Map<String, Value>, (u16, Value)> = match read(ct, &bytes) {
                Err(BodyFail::Decode(e)) => Err((422, json!({"detail": [e]}))),
                Err(BodyFail::Parse) => Err((400, json!({"detail": "There was an error parsing the body"}))),
                Err(BodyFail::Internal) => Err((500, Value::Null)),
                Ok(b) => body(model_of(path), &b).map_err(|e| (422, json!({"detail": e}))),
            };
            let status = c["status"].as_u64().unwrap() as u16;
            let answer = &c["answer"];
            let expect_error = (status == 422 && answer["detail"].is_array())
                || (status == 400 && answer["detail"] == "There was an error parsing the body");
            let ok = match (&got, expect_error) {
                (Err((s, a)), true) => *s == status && vexa_native_kit::pyjson::py_dumps(a) == vexa_native_kit::pyjson::py_dumps(answer),
                (Ok(_), false) => true,
                _ => false,
            };
            if !ok {
                failed.push(format!("{path} {} -> expected {status} {answer}, got {got:?}", c["body"].as_str().unwrap_or("").chars().take(200).collect::<String>()));
            }
        }
        assert!(failed.is_empty(), "{} of {} cases differ:
{}", failed.len(), cases.len(), failed.iter().take(25).cloned().collect::<Vec<_>>().join("
"));
    }

    #[test]
    fn content_types() {
        assert_eq!(read(Some("application/json; charset=utf-8"), b"{}"), Ok(Body::Json(json!({}))));
        assert_eq!(read(Some("Application/Problem+JSON"), b"[]"), Ok(Body::Json(json!([]))));
        assert_eq!(read(Some("text/plain"), b"{}"), Ok(Body::Raw("{}".into())));
        assert_eq!(read(None, b"{}"), Ok(Body::Raw("{}".into())));
        assert_eq!(read(Some("application/json"), b"null"), Ok(Body::Missing));
        assert_eq!(read(Some("application/json"), b""), Ok(Body::Missing));
    }
}
